properties.property:
[
  {
    "text": "Hello, planeswalker {var=player_name}.",
    "options": [
      {
        "name": "Why am I here?",
        "condition": [
          {
            "checkQuestFlag": "mainQuest",
            "not": true
          },
          {
            "checkCharacterFlag": "noQuest",
            "not": true
          }
        ],
        "text": "Easy - breathe. The stasis takes time to shed. You are awake, Guardian... after three thousand years, you are awake. This cave was your prison. And this plane is what remains of your realm.",
        "options": [
          {
            "name": "(Continue)",
            "text": "You remember the Night of Chains? Five walkers. Five Seals, cut from your own stolen power. A realm left to grey and die while you slept beneath it. They have returned - their castles stand at the compass points, and their colors crawl across the ash, claiming what was never theirs.",
            "options": [
              {
                "name": "(Continue)",
                "text": "I am the last Warden. My order kept your vigil for a hundred generations, and died waiting for this day. So rebuild, Guardian. Raise Orazca. Gather the survivors. And when you are strong - take back the five Seals from the five thrones.",
                "options": [
                  {
                    "name": "(Continue)",
                    "text": "Take this rune. It will carry you home from anywhere in the realm - and home is Orazca, the ruin at the heart of the star, a few hundred paces from this cave's mouth. That is where I will be. The realm waited three thousand years for you, Guardian; do not make it wait again.",
                    "action": [
                      {
                        "grantRewards": [
                          {
                            "type": "item",
                            "count": 1,
                            "itemName": "Homeward rune"
                          }
                        ]
                      }
                    ],
                    "options": [
                      {
                        "name": "Thank you.",
                        "text": "I will reopen the portal now. On the other side lie the ash-barrens of the Forsaken Realms - your realm, Guardian, grey as it is. Walk to the broken stones you will see from the cave mouth: that was Orazca. I will be waiting there. Bring the color back.",
                        "options": [
                          {
                            "name": "(Leave)",
                            "action": [
                              {
                                "setQuestFlag": {
                                  "key": "mainQuest",
                                  "val": 1
                                },
                                "activateMapObject": 78,
                                "deleteMapObject": 69
                              }
                            ]
                          }
                        ]
                      }
                    ]
                  }
                ]
              }
            ]
          }
        ]
      },
      {
        "name": "Goodbye."
      }
    ],
    "condition": [
      {
        "checkQuestFlag": "mainQuest",
        "not": true
      }
    ]
  },
  {
    "text": "The Warden has rolled up his maps and banked the fire. \"Nothing is left for either of us in this hole, Guardian,\" he says, shouldering his pack. \"Orazca is a few hundred paces out - the broken stones at the heart of the star. Come and find me there.\"",
    "options": [
      {
        "name": "(Leave)",
        "action": [
          {
            "deleteMapObject": 69
          }
        ]
      }
    ],
    "condition": [
      {
        "getQuestFlag": {
          "key": "mainQuest",
          "op": ">=",
          "val": 1
        }
      }
    ]
  }
]

[
{
   "text": "A flagstone rocks under your boot. Beneath it, wrapped in oilskin and sealed with your people's old crest, lies a single card someone hid here long ago - for whoever came home next.",
   "options": [{
      "name": "(Take the card)",
      "action": [{
         "deleteMapObject":-1
         },{
         "grantRewards": [{
            "type": "card",
            "count": 1,
            "rarity": ["Rare"],
            "colors": ["startingColor"],
            "raceEditions": true
         }]
      }]
   }]
}
]
